package com.evchargecalculator;

import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.content.res.ColorStateList;import android.text.*;import android.view.*;import android.widget.*;import android.graphics.drawable.GradientDrawable;import java.text.DecimalFormat;import java.text.DecimalFormatSymbols;import java.util.*;

public class MainActivity extends Activity {
 ScrollView scroll; LinearLayout root; PremiumBackgroundView background; EditText battery,power,price,departure,xguard; SeekBar batS; BatteryRangeView range; Switch xSwitch; TextView timeR,energyR,costR,statusR,startCalculated,themeButton; boolean busy,dark=false; SharedPreferences prefs;
 int blue=Color.rgb(27,139,220), green=Color.rgb(50,190,155), white=Color.rgb(25,38,58), secondary=Color.rgb(82,104,130), cardLight=Color.argb(235,255,255,255), cardDark=Color.argb(218,17,25,39);
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);prefs=getSharedPreferences("settings",0);int mode=prefs.getInt("theme",-1); if(mode==0) dark=false; else if(mode==1) dark=true; else dark=(getResources().getConfiguration().uiMode & 0x30)==0x20; build();applyTheme();calculate();}
 int text(){return dark?Color.rgb(245,248,255):white;} int sub(){return dark?Color.rgb(170,183,204):secondary;}
 TextView tv(String s,int sp,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);return t;}
 GradientDrawable bg(int color,float r,int stroke){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(r);if(stroke>0)g.setStroke(1,dark?Color.rgb(38,59,85):Color.rgb(215,225,235));return g;}
 EditText edit(String val){EditText e=new EditText(this);e.setText(val);e.setTextColor(text());e.setTextSize(18);e.setSingleLine();e.setGravity(Gravity.CENTER);e.setBackground(bg(dark?Color.rgb(21,34,51):Color.rgb(246,249,253),12,1));e.setPadding(10,0,10,0);e.setSelectAllOnFocus(true);e.setOnFocusChangeListener((v,f)->{if(f)new Handler().postDelayed(()->scroll.smoothScrollTo(0,Math.max(0,v.getBottom()-scroll.getHeight()+100)),180);});return e;}
 LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(20),dp(20),dp(20),dp(20));l.setBackground(bg(dark?cardDark:cardLight,22,1));return l;}
 SeekBar seek(int max,int progress){SeekBar s=new SeekBar(this);s.setMax(max);s.setProgress(progress);s.setProgressTintList(ColorStateList.valueOf(blue));s.setThumbTintList(ColorStateList.valueOf(blue));s.setBackgroundTintList(ColorStateList.valueOf(dark?Color.rgb(52,68,90):Color.rgb(220,230,240)));s.setPadding(4,0,4,0);return s;}
 void row(LinearLayout p,String label,EditText e,String unit){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);TextView l=tv(label,14,sub());r.addView(l,new LinearLayout.LayoutParams(0,54,1));r.addView(e,new LinearLayout.LayoutParams(dp(88),54));TextView u=tv(unit,13,sub());u.setGravity(Gravity.CENTER);r.addView(u,new LinearLayout.LayoutParams(dp(58),54));p.addView(r);}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 void build(){FrameLayout frame=new FrameLayout(this);background=new PremiumBackgroundView(this);frame.addView(background,new FrameLayout.LayoutParams(-1,-1));scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(30),dp(18),dp(18));scroll.addView(root);frame.addView(scroll,new FrameLayout.LayoutParams(-1,-1));setContentView(frame);
  LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView icon=tv("⚡",30,text());head.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(58)));TextView titleBox=tv("EV Charge Calculator",22,text());titleBox.setTypeface(null,1);head.addView(titleBox,new LinearLayout.LayoutParams(0,dp(72),1));root.addView(head);space(10);
  LinearLayout c1=card();TextView h1=tv("Batería",18,text());h1.setTypeface(null,1);c1.addView(h1);battery=edit("80,0");row(c1,"Capacidad",battery,"kWh");batS=seek(300,160);c1.addView(batS,new LinearLayout.LayoutParams(-1,dp(42)));c1.addView(tv("Carga inicial y objetivo",14,sub()));range=new BatteryRangeView(this);c1.addView(range,new LinearLayout.LayoutParams(-1,dp(72)));root.addView(c1);space(20);
  LinearLayout c2=card();TextView h2=tv("Carga",18,text());h2.setTypeface(null,1);c2.addView(h2);power=edit("3,45");row(c2,"Potencia",power,"kW");spaceIn(c2,10);price=edit("0,15");row(c2,"Precio energía",price,"€/kWh");spaceIn(c2,10);LinearLayout xr=new LinearLayout(this);xr.setGravity(Gravity.CENTER_VERTICAL);xr.addView(tv("Centinela / XGuard (consumo / 24 h)",14,sub()),new LinearLayout.LayoutParams(0,54,1));xSwitch=new Switch(this);xSwitch.setChecked(true);xr.addView(xSwitch);xguard=edit("5,0");xr.addView(xguard,new LinearLayout.LayoutParams(dp(70),dp(42)));xr.addView(tv("%",13,sub()),new LinearLayout.LayoutParams(dp(28),dp(42)));c2.addView(xr);root.addView(c2);space(14);
  LinearLayout c3=card();TextView h3=tv("Hora Salida",18,text());h3.setTypeface(null,1);c3.addView(h3);departure=edit("07:00");departure.setInputType(2);departure.setOnClickListener(v->pickTime(departure));row(c3,"Hora Salida",departure,"🕐");LinearLayout rr=new LinearLayout(this);rr.setGravity(Gravity.CENTER_VERTICAL);rr.addView(tv("Inicio recomendado",14,sub()),new LinearLayout.LayoutParams(0,54,1));startCalculated=tv("03:00",16,text());startCalculated.setGravity(Gravity.CENTER);startCalculated.setBackground(bg(dark?Color.rgb(21,34,51):Color.rgb(246,249,253),12,1));rr.addView(startCalculated,new LinearLayout.LayoutParams(dp(88),54));rr.addView(tv("🕐",13,sub()),new LinearLayout.LayoutParams(dp(58),54));c3.addView(rr);root.addView(c3);space(14);
  LinearLayout c4=card();TextView h4=tv("Resultado",18,text());h4.setTypeface(null,1);c4.addView(h4);timeR=tv("00 h 00 min",30,text());timeR.setTypeface(null,1);c4.addView(timeR);energyR=tv("0,0 kWh",17,blue);c4.addView(energyR);costR=tv("0,00 €",16,sub());c4.addView(costR);statusR=tv("",15,Color.WHITE);statusR.setTypeface(null,1);c4.addView(statusR);root.addView(c4);space(10);TextView foot=tv("Powered by EV Charge Calculator · v1.1",12,sub());foot.setGravity(Gravity.CENTER);root.addView(foot);space(8);themeButton=tv(dark?"☀ CLARO":"🌙 OSCURO",14,blue);themeButton.setGravity(Gravity.CENTER);themeButton.setBackground(bg(dark?Color.argb(50,54,184,255):Color.rgb(225,239,250),16,1));themeButton.setOnClickListener(v->toggleTheme());root.addView(themeButton,new LinearLayout.LayoutParams(-1,dp(48)));setup();}
 void space(int n){Space s=new Space(this);root.addView(s,new LinearLayout.LayoutParams(1,dp(n)));} void spaceIn(LinearLayout p,int n){Space s=new Space(this);p.addView(s,new LinearLayout.LayoutParams(1,dp(n)));}
 void applyTheme(){background.setDark(dark);getWindow().setStatusBarColor(dark?Color.rgb(7,11,18):Color.rgb(242,247,252));getWindow().setNavigationBarColor(dark?Color.rgb(7,11,18):Color.rgb(242,247,252));getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);themeButton.setText(dark?"☀ CLARO":"🌙 OSCURO");themeButton.setTextColor(blue);themeButton.setBackground(bg(dark?Color.argb(50,54,184,255):Color.rgb(225,239,250),16,1));}
 void toggleTheme(){dark=!dark;prefs.edit().putInt("theme",dark?1:0).apply();rebuildTheme();}
 void rebuildTheme(){String b=battery==null?"80,0":battery.getText().toString();String pw=power==null?"3,45":power.getText().toString();String pr=price==null?"0,15":price.getText().toString();String dep=departure==null?"07:00":departure.getText().toString();String xg=xguard==null?"5,0":xguard.getText().toString();int rc=range==null?30:range.getCurrent();int rt=range==null?80:range.getTarget();boolean xs=xSwitch!=null&&xSwitch.isChecked();build();battery.setText(b);power.setText(pw);price.setText(pr);departure.setText(dep);xguard.setText(xg);range.setValues(rc,rt);xSwitch.setChecked(xs);xguard.setEnabled(xs);applyTheme();calculate();}
 void pickTime(EditText e){String[] a=e.getText().toString().split(":");int h=7,m=0;try{h=Integer.parseInt(a[0]);m=Integer.parseInt(a[1]);}catch(Exception ignored){}new TimePickerDialog(this,(v,hh,mm)->{setText(e,String.format(Locale.US,"%02d:%02d",hh,mm));calculate();},h,m,true).show();}
 void setup(){batS.setOnSeekBarChangeListener(slider(v->setText(battery,fmt(v/2.0,1))));range.setListener((c,t)->calculate());battery.addTextChangedListener(watch(this::syncBat));power.addTextChangedListener(watch(this::calculate));price.addTextChangedListener(watch(this::calculate));xguard.addTextChangedListener(watch(this::calculate));departure.addTextChangedListener(watch(this::calculate));xSwitch.setOnCheckedChangeListener((b,c)->{xguard.setEnabled(c);calculate();});}
 SeekBar.OnSeekBarChangeListener slider(java.util.function.IntConsumer f){return new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean from){if(from&&!busy){busy=true;f.accept(p);busy=false;calculate();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}};}
 TextWatcher watch(Runnable r){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){if(!busy)r.run();}public void afterTextChanged(Editable e){}};}
 void setText(EditText e,String s){e.setText(s);e.setSelection(e.length());}
 void syncBat(){if(busy)return;double v=num(battery);if(v>=20&&v<=150){busy=true;batS.setProgress((int)Math.round(v*2));busy=false;}calculate();}
 double num(EditText e){try{return Double.parseDouble(e.getText().toString().replace(',','.'));}catch(Exception x){return 0;}}
 String fmt(double v,int d){DecimalFormat f=new DecimalFormat("0."+"0".repeat(d),DecimalFormatSymbols.getInstance(Locale.US));return f.format(v).replace('.',',');}
 int minutes(String s){try{String[] a=s.trim().split(":");return Integer.parseInt(a[0])*60+Integer.parseInt(a[1]);}catch(Exception e){return -1;}}
 void calculate(){if(battery==null)return;double cap=num(battery),st=range.getCurrent(),tar=range.getTarget(),kw=num(power),eur=num(price),x=num(xguard);if(cap<=0||kw<=0||tar<=st){timeR.setText("00 h 00 min");energyR.setText("0,0 kWh");costR.setText("0,00 €");statusR.setText("El objetivo debe ser mayor que el nivel inicial.");statusR.setTextColor(Color.rgb(255,107,122));return;}int dm=minutes(departure.getText().toString());if(dm<0){statusR.setText("Selecciona una hora de salida válida.");statusR.setTextColor(Color.rgb(255,107,122));return;}double base=cap*(tar-st)/100.0;double baseMin=base/kw*60.0;double factor=xSwitch.isChecked()?cap*x/(100.0*24.0*kw):0;double mins=baseMin/(1.0-factor);if(factor>=1.0||mins>1440){timeR.setText("> 24 h");statusR.setText("⚠ No es posible alcanzar el objetivo en 24 horas con esta configuración.");statusR.setTextColor(Color.rgb(255,107,122));return;}double extra=xSwitch.isChecked()?cap*x/100.0*(mins/1440.0):0;double energy=base+extra;timeR.setText(String.format(Locale.US,"%02d h %02d min",(int)(mins/60),(int)Math.round(mins%60)));energyR.setText(fmt(energy,1)+" kWh");costR.setText(fmt(energy*eur,2)+" €");int start=(int)Math.round(dm-mins);start=((start%1440)+1440)%1440;startCalculated.setText(String.format(Locale.US,"%02d:%02d",start/60,start%60));if(mins<=1440){statusR.setText("✓ Inicio recomendado para llegar al objetivo antes de la salida.");statusR.setTextColor(Color.rgb(83,224,185));}}
}
